static Control Template(string template, IReadOnlyDictionary<string, int> slots)
{
    var stack = new StackPanel { Spacing = 4 };
    foreach (var line in template.Split('\n'))
    {
        var flow = new WrapPanel { Orientation = Orientation.Horizontal };
        // 普通文字按词排，{{name}} 换成 K.Token（按 slot 取系列色）
        foreach (var part in line.Split(' '))
        {
            flow.Children.Add(part.StartsWith("{{") && part.EndsWith("}}")
                ? K.Token(part.Trim('{', '}'), slots.TryGetValue(part.Trim('{', '}'), out var slot) ? slot : 0)
                : new TextBlock { Text = part, FontFamily = K.MonoFamily, FontSize = 12 });
        }

        stack.Children.Add(flow);
    }

    return stack;
}
